const CACHE='cet6-v9';
const ASSETS=['./','./index.html','./style.css','./content.js','./vocabulary.js','./materials.js','./profiles.js','./dialogs.js','./library.js','./sources.js','./source-guide.json','./daily-feed.json','./LICENSE-DATA.txt','./core.js','./app.js','./pronunciation.js','./manifest.webmanifest','./icon.svg','./icon-192.png','./icon-512.png','./icon-maskable.png','./audio/garden.wav','./audio/garden-sentence.wav','./audio/library.wav','./audio/library-sentence.wav','./audio/culture.wav','./audio/culture-sentence.wav'];
self.addEventListener('install',event=>event.waitUntil((async()=>{const cache=await caches.open(CACHE);await cache.addAll(ASSETS);await cache.put('./offline-ready',new Response('ready'));await self.skipWaiting();})()));
self.addEventListener('activate',event=>event.waitUntil((async()=>{for(const key of await caches.keys())if(key.startsWith('cet6-')&&key!==CACHE)await caches.delete(key);await self.clients.claim();for(const client of await self.clients.matchAll())client.postMessage('offline-ready');})()));
self.addEventListener('fetch',event=>{const req=event.request,url=new URL(req.url);if(req.method!=='GET'||url.origin!==self.location.origin)return;event.respondWith((async()=>{const cache=await caches.open(CACHE);if(url.pathname.endsWith('/daily-feed.json')||url.pathname.endsWith('/api/news')){try{const live=await fetch(req);if(live.ok){await cache.put(url.href,live.clone());return live;}throw Error('更新失败');}catch(e){const prior=await cache.match(url.href);if(prior){if(url.pathname.endsWith('/api/news')){const json=await prior.json();json.status='stale';return new Response(JSON.stringify(json),{headers:{'Content-Type':'application/json'}});}return prior;}return new Response(JSON.stringify({status:'unavailable',items:[]}),{status:503,headers:{'Content-Type':'application/json'}});}}const cached=await cache.match(url.href);if(cached){if(req.headers.has('range')&&url.pathname.endsWith('.wav')){const bytes=await cached.arrayBuffer(),range=req.headers.get('range'),m=/^bytes=(\d+)-(\d*)$/.exec(range);if(!m)return new Response(null,{status:416});const start=Number(m[1]),end=m[2]?Math.min(Number(m[2]),bytes.byteLength-1):bytes.byteLength-1;if(start>end)return new Response(null,{status:416,headers:{'Content-Range':`bytes */${bytes.byteLength}`}});return new Response(bytes.slice(start,end+1),{status:206,headers:{'Content-Type':'audio/wav','Content-Range':`bytes ${start}-${end}/${bytes.byteLength}`,'Accept-Ranges':'bytes','Content-Length':String(end-start+1)}});}return cached;}try{return await fetch(req);}catch(e){if(req.mode==='navigate')return (await cache.match('./index.html'))||new Response('离线资源未准备好',{status:503});return new Response('Offline',{status:503});}})());});

